
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_q2d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_q2d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243233073000478e+00, -4.160533886167235e+00, -4.044711650855355e+00, -3.884393693670282e+00, -3.666202971751461e+00, -3.376362457869649e+00, -3.004464224529784e+00, -2.550131708896254e+00, -2.030849145441019e+00, -1.476829677007149e+00, -9.170118566724257e-01, -6.911579697120640e-01, -5.966170807386471e-01, -4.887738947599242e-01, -3.475882255380649e-01, -1.883571151563255e-01, -2.449015326204572e-02, -4.250048076379977e-03, -4.710612557320060e-04, -1.807947745751380e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


